396	// amendOrPrintTrailer amends HEAD with the checkpoint trailer (best-effort).
397	// If the amend fails, it logs the full error, prints a brief reason to stderr
398	// so the user knows the amend was attempted, and falls back to printing the
399	// trailer for manual paste. The recovery path is non-fatal: attach still
400	// succeeds.
401	func amendOrPrintTrailer(logCtx context.Context, w, errW io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) {
402		if err := promptAmendCommit(logCtx, w, headCommit, checkpointIDStr, force); err != nil {
403			logging.Warn(logCtx, "failed to amend commit", "error", err)
404			// promptAmendCommit wraps the full multi-line `git commit --amend`
405			// output into the error; keep the stderr note to the first line so it
406			// stays brief. The full error is preserved in the debug log above.
407			fmt.Fprintf(errW, "Could not amend the commit automatically (%s).\n", firstLine(err.Error()))
408			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
409		}
410	}
